#!/usr/bin/env python3
"""
check-v2-diff.py : runs the UNCHANGED v2 suite (../../golden-tests) against the current JavaScript engine and proves that every
failure is a vector the v1.1 manifest lists as removed or changed (intentional). Any other failure = unintended regression -> exit 1.
Rewrites ../baseline-diff.md.   Usage: python -I check-v2-diff.py [NODE]
"""
import json, os, subprocess, sys, tempfile
HERE = os.path.dirname(os.path.abspath(__file__)); SUITE = os.path.join(HERE, ".."); V2 = os.path.join(SUITE, "..", "golden-tests")
node = sys.argv[1] if len(sys.argv) > 1 else "node"
out = os.path.join(tempfile.mkdtemp(), "v2.json")
cmd = [sys.executable, "-I", "dictation-golden-test-runner.py", "--adapter", '"%s" ../hybrid-engine/test/golden-adapter.js golden-tests' % node, "--adapter-only", "--json", out]
subprocess.run(cmd, cwd=V2, capture_output=True, text=True, encoding="utf-8")
r = json.load(open(out)); m = json.load(open(os.path.join(SUITE, "vector-status-manifest.json"), encoding="utf-8"))
fails = sorted(i for g, i, d in r["failures"] if g == "adapter"); rem = set(m["removed"]); chg = {k for k, v in m["vectors"].items() if v["status"] == "changed"}
unexpected = sorted(set(fails) - rem - chg); ad = r["adapter"]
L = ["# Baseline difference report: v2 suite (contract v1) on the v1.1 engine", "", "Generated by `tools/check-v2-diff.py` (rerun it after any engine change). Command it runs, from `pkg/golden-tests/` (the **unchanged** v2 suite):", "", "```",
     'python -I dictation-golden-test-runner.py --adapter "node ../hybrid-engine/test/golden-adapter.js golden-tests" --adapter-only', "```", "",
     "Result: ADAPTER ENGINE %d passed, %d failed, %d unsupported (242 vectors; 4 need a UI)." % (ad["passed"], ad["failed"], ad["unsupported"]), "",
     "Every failure must be a vector that `vector-status-manifest.json` lists as **removed** or **changed** for v1.1. Anything else is an unintended regression.", "",
     "| Class | Count | Vectors |", "|---|---|---|",
     "| failing, intentionally **removed** in v1.1 | %d | %s |" % (len(set(fails) & rem), ", ".join(sorted(set(fails) & rem))),
     "| failing, intentionally **changed** in v1.1 | %d | %s |" % (len(set(fails) & chg), ", ".join(sorted(set(fails) & chg))),
     "| failing, **not** in the manifest (unintended regression) | %d | %s |" % (len(unexpected), ", ".join(unexpected) or "none"),
     "| removed in v1.1 but still passing on the new engine | %d | %s (they expect \"locked\"; the legacy `setting` input is ignored and 0 valid checks gives locked) |" % (len(rem - set(fails)), ", ".join(sorted(rem - set(fails)))),
     "", "Why: removed = hint, reveal, assisted/novel evidence and the `after_reveal` / `after_first_attempt_checked` settings no longer exist (owner policy 2026-11); changed = the same vectors without those fields, and homework session vectors where a draft Check became a draft `answer` event (homework has no scored Check before submission). Per-vector reasons: `vector-status-manifest.json`."]
open(os.path.join(SUITE, "baseline-diff.md"), "w", encoding="utf-8", newline="\n").write("\n".join(L) + "\n")
print("v2 suite on the v1.1 engine: %d passed, %d failed (%d removed, %d changed, %d UNEXPECTED), %d unsupported" % (ad["passed"], ad["failed"], len(set(fails) & rem), len(set(fails) & chg), len(unexpected), ad["unsupported"]))
sys.exit(1 if unexpected else 0)
